learning_path:
{
  "path": [
    {
      "step": 1,
      "course_id": "EDX283",
      "rationale": "Start with foundational knowledge of climate science and the greenhouse effect."
    },
    {
      "step": 2,
      "course_id": "EDX1987",
      "rationale": "Build on prior knowledge by learning about modeling climate change and its complexities."
    },
    {
      "step": 3,
      "course_id": "EDX2459",
      "rationale": "Understand the basics of climate change, energy balance, and emissions, as well as the role of nuclear power and electric vehicles."
    },
    {
      "step": 4,
      "course_id": "EDX570",
      "rationale": "Learn about sustainable energy and how to critically evaluate key features, opportunities, and challenges associated with modern energy technologies."
    },
    {
      "step": 5,
      "course_id": "EDX2822",
      "rationale": "Apply knowledge of thermodynamics and energy to understand different forms of energy and how to convert between them."
    },
    {
      "step": 6,
      "course_id": "EDX3079",
      "rationale": "Explain and apply the Second and Third Laws of Thermodynamics to determine spontaneity of a process or reaction."
    },
    {
      "step": 7,
      "course_id": "EDX2381",
      "rationale": "Understand how natural systems are affected by people and appreciate your own impact on the environment."
    },
    {
      "step": 8,
      "course_id": "EDX1212",
      "rationale": "Learn how to recognize the social and psychological drivers of climate science denial and effectively debunk climate misinformation."
    },
    {
      "step": 9,
      "course_id": "EDX880",
      "rationale": "Understand the current state of global challenges and develop the reflex to critically approach and verify statements around these topics."
    },
    {
      "step": 10,
      "course_id": "EDX695",
      "rationale": "Learn about environmental engineering, including air pollution and treatment, and the impact of climate change on our lives and environment."
    },
    {
      "step": 11,
      "course_id": "EDX2216",
      "rationale": "Review industrial sources of emissions and existing technological options to mitigate them, and describe how the electricity system works."
    },
    {
      "step": 12,
      "course_id": "EDX2530",
      "rationale": "Prepare for the AP Environmental Science Exam by reviewing material on the Living World, Pollution, Resources, Populations, and Environmental Issues."
    },
    {
      "step": 13,
      "course_id": "EDX1173",
      "rationale": "Develop essential skills to achieve sustainable change and apply them to a sustainability issue in your own environment."
    },
    {
      "step": 14,
      "course_id": "EDX2140",
      "rationale": "Understand the impact of the energy transition on energy markets, including the introduction of renewable energy sources and storage technologies."
    },
    {
      "step": 15,
      "course_id": "EDX2529",
      "rationale": "Learn about the different processes of the global water cycle and the challenges in better understanding and adapting to the impact of climate change on water."
    },
    {
      "step": 16,
      "course_id": "EDX2346",
      "rationale": "Understand what the different heating, cooling, and electricity generation systems are and how to combine the concept of efficiency with the building's energy demand."
    },
    {
      "step": 17,
      "course_id": "EDX1172",
      "rationale": "Learn about carbon capture and storage technology and its role in protecting the atmosphere from excess carbon dioxide."
    },
    {
      "step": 18,
      "course_id": "EDX171",
      "rationale": "Develop fundamental field skills and techniques in the earth and environmental sciences, including navigation, observation, and data collection."
    },
    {
      "step": 19,
      "course_id": "EDX3029",
      "rationale": "Explain and apply the Second and Third Laws of Thermodynamics to determine spontaneity of a process or reaction."
    },
    {
      "step": 20,
      "course_id": "EDX1026",
      "rationale": "Prepare for the AP Environmental Science Exam by reviewing material on Pollution and Resources, including multiple-choice, free-response, and exam practice."
    },
    {
      "step": 21,
      "course_id": "EDX3003",
      "rationale": "Understand the various roles of scientists across the spectrum of engagement with environmental management and develop strategies for science and management engagement."
    },
    {
      "step": 22,
      "course_id": "EDX529",
      "rationale": "Develop a plan for initiating and sustaining a citizen science project, including strategies and skills for communication, data collection, and management."
    },
    {
      "step": 23,
      "course_id": "EDX1265",
      "rationale": "Identify the different elements of the energy system, such as power system technology, policy, and regulation, and explain how they interact and contribute to energy systems integration."
    },
    {
      "step": 24,
      "course_id": "EDX369",
      "rationale": "Learn about fluid mechanics and thermodynamic processes, including the concept of function in mathematics and the significance of electrochemistry."
    },
    {
      "step": 25,
      "course_id": "EDX838",
      "rationale": "Prepare for the AP Environmental Science Exam by reviewing material on the Living World, including multiple-choice, free-response, and exam practice."
    },
    {
      "step": 26,
      "course_id": "EDX2660",
      "rationale": "Learn about the basics of nuclear science and nuclear energy, including the operating principles of nuclear reactors and the nuclear fuel cycle."
    },
    {
      "step": 27,
      "course_id": "EDX97",
      "rationale": "Estimate the most important heat losses and gains in a building and achieve thermal balance to determine its space heating and cooling needs."
    },
    {
      "step": 28,
      "course_id": "EDX2089",
      "rationale": "Understand the role of air, water, and wind in weather systems and how to estimate local wind speed and direction."
    },
    {
      "step": 29,
      "course_id": "EDX1303",
      "rationale": "Develop essential skills to achieve sustainable change and apply them to a sustainability issue in your own environment."
    },
    {
      "step": 30,
      "course_id": "EDX989",
      "rationale": "Explain and apply the Second and Third Laws of Thermodynamics to determine spontaneity of a process or reaction."
    },
    {
      "step": 31,
      "course_id": "EDX638",
      "rationale": "Understand the significance of electrochemistry and how it relates to other fields of science and real-life applications."
    },
    {
      "step": 32,
      "course_id": "EDX1890",
      "rationale": "Understand the basics of the Sustainable Development Goals and the role of people, the planet, and sustainable consumption of natural resources."
    },
    {
      "step": 33,
      "course_id": "EDX2800",
      "rationale": "Learn about fundamental thermodynamics, acid-base chemistry, redox and electrochemistry, and transition metal chemistry."
    },
    {
      "step": 34,
      "course_id": "EDX2937",
      "rationale": "Understand what thermodynamic functions govern heterogeneous equilibria and how to calculate these functions from measurable materials properties."
    },
    {
      "step": 35,
      "course_id": "EDX2482",
      "rationale": "Understand the Anthropocene, tipping points, and resilience thinking, including the social-ecological implications of sustainability."
    },
    {
      "step": 36,
      "course_id": "EDX627",
      "rationale": "Learn about nuclear energy, including common and not-so-common sources of radiation, and the basic idea behind fusion energy."
    },
    {
      "step": 37,
      "course_id": "EDX2137",
      "rationale": "Develop skills in precalculus, including making conjectures, constructing logical arguments, and justifying reasoning."
    },
    {
      "step": 38,
      "course_id": "EDX242",
      "rationale": "Understand the role of citizen science in public and environmental health, including the steps involved in initiating, planning, and managing successful projects."
    },
    {
      "step": 39,
      "course_id": "EDX3205",
      "rationale": "Estimate corporate carbon footprint and identify hot spots in the supply chain, and account for environmental estimations in supply chain and logistics decisions."
    },
    {
      "step": 40,
      "course_id": "EDX2886",
      "rationale": "Understand how to apply the knowledge base and skills learned throughout the series to a real-world problem and independently work on a data analysis project."
    },
    {
      "step": 41,
      "course_id": "EDX1226",
      "rationale": "Practice using Python to solve real data science challenges, including data analysis, machine learning, and data visualization."
    },
    {
      "step": 42,
      "course_id": "EDX2671",
      "rationale": "Understand the digital transformation in the energy sector, including challenges and solutions, and evaluate its impact on both the power system and society."
    },
    {
